namespace BetaFit.Desktop.Controls;
public sealed class UcStatCard:UserControl {private readonly Label _value;public UcStatCard():this("Estatística"){}public UcStatCard(string title){BackColor=Color.FromArgb(28,34,43);Padding=new Padding(18);Dock=DockStyle.Fill;var t=new Label{Text=title,Dock=DockStyle.Top,Height=25,ForeColor=Color.Silver,Font=new Font("Segoe UI",9)};_value=new Label{Text="0",Dock=DockStyle.Fill,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",24),TextAlign=ContentAlignment.MiddleLeft};Controls.Add(_value);Controls.Add(t);}public void SetValue(int v)=>_value.Text=v.ToString("N0");}